const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const items=computed(()=>[
 {name:tr('Vincular cuenta','Link account'),description:tr('Un número registrado por el encargado se activa al escribir por primera vez. Si no está registrado, se usa el código de la cuenta.','A pre-registered number activates on its first message. Otherwise, use the account linking code.'),permission:tr('Usuarios habilitados de la iglesia piloto','Enabled pilot church users'),example:'Hola / VINCULAR <código>',limit:tr('El código vence en diez minutos. Nunca compartas códigos.','The code expires in ten minutes. Never share codes.')},
